import '../../../core/network/api_client.dart';class PatientProfile{PatientProfile({required this.id,required this.fullName,required this.email,this.dateOfBirth,this.gender});factory PatientProfile.fromJson(Map<String,dynamic> j)=>PatientProfile(id:j['patientId'] as String,fullName:j['fullName'] as String,email:j['email'] as String,dateOfBirth:j['dateOfBirth'] as String?,gender:j['gender'] as String?);final String id,fullName,email;final String? dateOfBirth,gender;}class ProfileRepository{ProfileRepository(this._client);final ApiClient _client;Future<PatientProfile>get()async{final r=await _client.dio.get<Map<String,dynamic>>('/api/patient/profile');return PatientProfile.fromJson(r.data!);}Future<void>update(String name,String? dob,String? gender)=>_client.dio.put<void>('/api/patient/profile',data:{'fullName':name,'dateOfBirth':dob,'gender':gender});}